17	    const atb::SVector<atb::TensorDesc> &inTensorDesc, atb::SVector<atb::TensorDesc> &outTensorDesc) const
18	{
19	    LOG_INFO(opName_ + " InferShape start");
20	    outTensorDesc.at(0).format = inTensorDesc.at(0).format;
21	    outTensorDesc.at(0).dtype = inTensorDesc.at(0).dtype;
22	    outTensorDesc.at(0).shape.dimNum = inTensorDesc.at(0).shape.dimNum;
23	
24	    if (inTensorDesc.at(0).shape.dimNum == DIM3) {
25	        LOG_INFO("[input0 dimNum = 3] CHECK " + opName_ + " input shape: [input0] " +
26	                 std::to_string(inTensorDesc.at(0).shape.dims[DIM0]) + ", " +
27	                 std::to_string(inTensorDesc.at(0).shape.dims[DIM1]) + ", " +
28	                 std::to_string(inTensorDesc.at(0).shape.dims[DIM2]));
29	        outTensorDesc.at(0).shape.dims[DIM0] = inTensorDesc.at(0).shape.dims[DIM0];
30	        outTensorDesc.at(0).shape.dims[DIM1] = inTensorDesc.at(0).shape.dims[DIM1];
31	        outTensorDesc.at(0).shape.dims[DIM2] = inTensorDesc.at(0).shape.dims[DIM2];
32	    } else if (inTensorDesc.at(0).shape.dimNum == DIM2) {
33	        LOG_INFO("[input0 dimNum = 2] CHECK " + opName_ + " input shape: [input0] " +
34	                 std::to_string(inTensorDesc.at(0).shape.dims[DIM0]) + ", " +
35	                 std::to_string(inTensorDesc.at(0).shape.dims[DIM1]));
36	        outTensorDesc.at(0).shape.dims[DIM0] = inTensorDesc.at(0).shape.dims[DIM0];
37	        outTensorDesc.at(0).shape.dims[DIM1] = inTensorDesc.at(0).shape.dims[DIM1];
38	    } else {
39	        LOG_ERROR(opName_ + " invalid dimNum = " + std::to_string(inTensorDesc.at(0).shape.dimNum));
40	    }
41	
42	    LOG_INFO(opName_ + " InferShape end");
