57	atb::Status GeluOperation::CreateAclnnVariantPack(const atb::VariantPack &variantPack)
58	{
59	    LOG_INFO(opName_ + " CreateAclnnVariantPack start");
60	
61	    auto ret = CreateAclnnInTensor(variantPack);
62	    if (ret != 0) {
63	        LOG_ERROR(opName_ + " CreateAclnnInTensor fail");
64	        return atb::ERROR_INVALID_PARAM;
65	    }
66	
67	    ret = CreateAclnnOutTensor(variantPack);
68	    if (ret != 0) {
69	        LOG_ERROR(opName_ + " CreateAclNNOutTensorVariantPack fail");
70	        return atb::ERROR_INVALID_PARAM;
71	    }
72	
73	    LOG_INFO(opName_ + " CreateAclnnVariantPack end");
74	    return atb::NO_ERROR;
75	}
