77	atb::Status GeluOperation::CreateAclnnInTensor(const atb::VariantPack &variantPack)
78	{
79	    aclInTensors_.resize(GetInputNum());
80	    for (size_t i = 0; i < aclInTensors_.size(); ++i) {
81	        auto aclnnTensor = CreateAclnnTensor(variantPack.inTensors.at(i), i);
82	        if (aclnnTensor->tensor == nullptr) {
83	            LOG_ERROR(opName_ + " InTensor aclCreateTensor index " + std::to_string(i) + " fail");
84	            return atb::ERROR_INTERNAL_ERROR;
85	        }
86	        aclInTensors_[i] = aclnnTensor;
87	    }
88	    return atb::NO_ERROR;
89	}
