91	atb::Status GeluOperation::CreateAclnnOutTensor(const atb::VariantPack &variantPack)
92	{
93	    aclOutTensors_.resize(GetOutputNum());
94	    for (size_t i = 0; i < aclOutTensors_.size(); ++i) {
95	        auto aclnnTensor = CreateAclnnTensor(variantPack.outTensors.at(i), i);
96	        if (aclnnTensor->tensor == nullptr) {
97	            LOG_ERROR(opName_ + " outTensor aclCreateTensor index " + std::to_string(i) + " fail");
98	            return atb::ERROR_INTERNAL_ERROR;
99	        }
100	        LOG_INFO(opName_ + " input[" + std::to_string(i) + "] CreateAclnnTensor start");
101	        aclOutTensors_[i] = aclnnTensor;
102	    }
103	    return atb::NO_ERROR;
104	}
