143	
144	    auto &node = nodes_.at(nodeId);
145	    atb::SVector<atb::TensorDesc> inTensorDescs;
146	    node.variantPack_.inTensors.resize(node.operation_->GetInputNum());
147	    inTensorDescs.resize(node.operation_->GetInputNum());
148	
149	    // 获取node中operation_的输入tensor desc
150	    for (size_t i = 0; i < node.inTensors_.size(); ++i) {
151	        node.variantPack_.inTensors.at(i) = *node.inTensors_.at(i);
152	        inTensorDescs.at(i) = node.inTensors_.at(i)->desc;
153	    }
154	
155	    atb::SVector<atb::TensorDesc> outTensorDescs;
156	    outTensorDescs.resize(node.operation_->GetOutputNum());
157	
158	    // 调用operation_的InferShape，推导出out tensor的desc
159	    atb::Status st = node.operation_->InferShape(inTensorDescs, outTensorDescs);
160	
161	    node.variantPack_.outTensors.resize(node.operation_->GetOutputNum());
162	    for (size_t i = 0; i < node.outTensors_.size(); ++i) {
163	        node.variantPack_.outTensors.at(i) = *node.outTensors_.at(i);
164	        if (node.outTensorTypes_.at(i) == TensorType::INTERNAL_TENSOR) {
165	            // 创建输出tensor的空间
166	            CreateTensorFromDesc(node.variantPack_.outTensors.at(i), outTensorDescs.at(i));
167	            *node.outTensors_.at(i) = node.variantPack_.outTensors.at(i);
168	        }
169	    }
170	    LOG_INFO("buildNodeVariantPack nodes[" + std::to_string(nodeId) + "] end");
171	}
