173	atb::Status Model::ExecuteNode(int nodeId)
174	{
175	    auto &node = nodes_.at(nodeId);
176	
177	    // 调用Setup接口
178	    uint64_t workspaceSize = 0;
179	    atb::Status status = node.operation_->Setup(node.variantPack_, workspaceSize, modeContext_);
180	    CHECK_RET(status, "Setup node " + std::to_string(nodeId) + " failed. status: " + std::to_string(status));
181	
182	    LOG_INFO("Get node[" + std::to_string(nodeId) + "] workspace size:" + std::to_string(workspaceSize));
183	
184	    // 分配workspace
185	#ifdef USE_MEMPOOL
186	    CreateWorkspaceBuffer(nodeId, workspaceSize);
187	#else
188	    if (workspaceSize != 0) {
189	        status = aclrtMalloc(&node.workspace_, workspaceSize, ACL_MEM_MALLOC_HUGE_FIRST);
190	        CHECK_RET(status, "alloc error!");
191	    }
192	#endif
193	
194	    // 调用Execute接口
195	    LOG_INFO("Execute node[" + std::to_string(nodeId) + "] start");
196	    status = node.operation_->Execute(node.variantPack_, (uint8_t *)(node.workspace_), workspaceSize, modeContext_);
197	    CHECK_RET(status, "Execute node " + std::to_string(nodeId) + " failed. status: " + std::to_string(status));
198	    LOG_INFO("Execute node[" + std::to_string(nodeId) + "] end");
199	    return atb::NO_ERROR;
200	}
