202	void Model::CreateWorkspaceBuffer(int nodeId, int workspaceSizeNeeded)
203	{
204	    auto &node = nodes_.at(nodeId);
205	    if (workspaceSizeNeeded == 0) {
206	        LOG_INFO("skip the workspacebuffer for size 0");
207	        return;
208	    }
209	    if (node.workspaceBlockId_ == -1 || node.workspaceSize_ == 0) {
210	        node.workspaceSize_ = workspaceSizeNeeded;
211	        GetMemoryManager().AllocateBlock(node.workspaceSize_, node.workspaceBlockId_);
212	    }
213	    if (node.workspaceSize_ < workspaceSizeNeeded) {
214	        GetMemoryManager().FreeBlock(node.workspaceBlockId_);
215	        GetMemoryManager().AllocateBlock(workspaceSizeNeeded, node.workspaceBlockId_);
216	        node.workspaceSize_ = workspaceSizeNeeded;
217	    }
218	
219	    GetMemoryManager().GetBlockPtr(node.workspaceBlockId_, node.workspace_);
220	}
