222	void Model::FreeResource()
223	{
224	    LOG_INFO("FreeResource start");
225	    auto status = aclrtDestroyStream(modelStream_);  // 销毁stream
226	    CHECK_RET(status, "aclrtDestroyStream failed");
227	
228	    // 释放operation
229	    for (auto &node : nodes_) {
230	        atb::DestroyOperation(node.operation_);
231	#ifdef USE_MEMPOOL
232	        GetMemoryManager().FreeBlock(node.workspaceBlockId_);
233	#endif
234	    }
235	
236	    status = atb::DestroyContext(modeContext_);  // 销毁context
237	    CHECK_RET(status, "aclrtDestroyStream failed");
238	
239	    // 销毁输入tensor
240	    for (size_t i = 0; i < modelInTensors_.size(); i++) {
241	        aclrtFree(modelInTensors_.at(i).deviceData);
242	    }
243	
244	    // 销毁输出tensor
245	    for (size_t i = 0; i < modelOutTensors_.size(); i++) {
246	        aclrtFree(modelOutTensors_.at(i).deviceData);
247	    }
248	
249	    // 释放中间tensor
250	    for (size_t i = 0; i < internalTensors_.size(); i++) {
251	        aclrtFree(internalTensors_.at(i).deviceData);
252	    }
253	
254	    aclrtResetDevice(deviceId_);  // 重置deviceId
255	    LOG_INFO("FreeResource end");
256	}
