258	void Model::WaitFinish()
259	{
260	    // step9：销毁创建的对象，释放内存
261	    // 流同步，作用是等待device侧任务计算完成
262	    auto ret = aclrtSynchronizeStream(modelStream_);
263	    CHECK_RET(ret, "sync error!");
